
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_lspbe_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_lspbe", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.303321038143794e+00, -4.221598580965400e+00, -4.107194698553747e+00, -3.948945360553461e+00, -3.733790315580723e+00, -3.448441457017620e+00, -3.083252354530357e+00, -2.639018881001062e+00, -2.135134274548931e+00, -1.608319167377855e+00, -1.084864164826053e+00, -7.090235732549505e-01, -6.021042177727213e-01, -5.012533829742508e-01, -3.701664719737778e-01, -2.419158846977434e-01, -1.308014209848918e-01, -4.294203708320944e-02, -7.390641129774950e-04, 1.373732535387981e-08]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


